(() => {
'use strict';
const D=window.MealData,E=window.MealEngine,STORE='family-table-test-v1';
const main=document.getElementById('main'),modalRoot=document.getElementById('modal-root');
const labels={breakfast:'早餐',lunch:'午餐',dinner:'晚餐',snack:'下午加餐'};
const groups={grain:'主食',protein:'鱼肉蛋豆',veg:'蔬菜',fruit:'水果',dairy:'奶类',nuts:'坚果种子',condiment:'调味'};
const cats={breakfast:'早餐组合',grain:'主食',protein:'蛋白质菜',veg:'蔬菜',snack:'加餐'};
const nutrients={kcal:['能量','千卡'],protein:['蛋白质','g'],carbs:['碳水化合物','g'],fat:['脂肪','g'],fiber:['膳食纤维','g'],sodium:['钠','mg'],calcium:['钙','mg']};
const baseFoodIds=Object.keys(D.foods);
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const addDay=(day,n)=>{const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
const monday=day=>{const d=new Date(day+'T12:00:00Z');return addDay(day,-((d.getUTCDay()+6)%7));};
const dateLabel=day=>{const d=new Date(day+'T12:00:00Z');return `${d.getUTCMonth()+1}月${d.getUTCDate()}日 ${['周日','周一','周二','周三','周四','周五','周六'][d.getUTCDay()]}`;};
const member=(id,name,extra={})=>({id,name,age:null,sex:'unknown',height:null,weight:null,stage:'adult',focus:[],specialDiet:true,profileConfirmed:false,portions:{grain:1,protein:1,veg:1,fruit:1,dairy:1,nuts:1},...extra});
function fresh(){return {version:1,catalogVersion:D.catalogVersion||1,house:'home',person:'me',planPerson:'me',day:today(),meal:'dinner',period:'day',view:'plan',filter:'all',shopRange:'week',bought:{},records:[],water:[],feedback:[],houses:{
 home:{name:'我家',city:'shanghai',plans:{},customRecipes:[],customFoods:{},members:[member('me','我'),member('partner','家人'),member('grandpa','爷爷',{stage:'elder'}),member('grandma','奶奶',{stage:'elder'}),member('child','孩子',{age:5,stage:'child',portions:{grain:.65,protein:.65,veg:.6,fruit:.7,dairy:1,nuts:.5}})]},
 care:{name:'照护家庭',city:'guangzhou',plans:{},customRecipes:[],customFoods:{},members:[member('caregiver','照护者'),member('elder1','长辈一',{stage:'care'}),member('elder2','长辈二',{stage:'care'})]},
 solo:{name:'一人食',city:'shanghai',plans:{},customRecipes:[],customFoods:{},members:[member('solo','我')]}}};}
function parseBackup(text){return JSON.parse(text,(key,value)=>{if(['__proto__','prototype','constructor'].includes(key))throw new Error('Invalid backup key');return value;});}
function validateBackup(data){
 const obj=v=>v!==null&&typeof v==='object'&&!Array.isArray(v),str=v=>typeof v==='string',num=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0;
 const id=v=>str(v)&&/^[A-Za-z0-9][A-Za-z0-9_-]{0,100}$/.test(v),date=v=>str(v)&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+'T12:00:00Z'))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;
 const strings=v=>Array.isArray(v)&&v.every(str),need=value=>{if(!value)throw new Error('Invalid backup structure');},spaces=['home','care','solo'];
 need(obj(data)&&data.version===1&&obj(data.houses)&&Object.keys(data.houses).length===3&&spaces.every(k=>obj(data.houses[k])));
 need(spaces.includes(data.house)&&date(data.day)&&Object.hasOwn(labels,data.meal)&&['day','week'].includes(data.period)&&['plan','shop','library','me'].includes(data.view)&&['day','week'].includes(data.shopRange)&&['all','prep','season','book',...Object.keys(cats)].includes(data.filter));
 for(const key of spaces){
  const space=data.houses[key];need(str(space.name)&&['shanghai','guangzhou'].includes(space.city)&&Array.isArray(space.members)&&space.members.length>0&&obj(space.plans)&&Array.isArray(space.customRecipes)&&obj(space.customFoods));
  const members=new Set();for(const p of space.members){need(obj(p)&&id(p.id)&&!members.has(p.id)&&str(p.name)&&p.name.trim()&&obj(p.portions)&&Object.values(p.portions).every(num)&&strings(p.focus)&&typeof p.specialDiet==='boolean'&&typeof p.profileConfirmed==='boolean'&&['unknown','male','female'].includes(p.sex)&&['adult','child','elder','care','lactating'].includes(p.stage));for(const v of [p.age,p.height,p.weight])need(v===null||num(v));if(p.notes!==undefined)need(str(p.notes));members.add(p.id);}
  const foodIds=new Set(baseFoodIds),recipeIds=new Set(D.recipes.concat(D.retiredRecipes||[]).map(r=>r.id));
  for(const [key,f] of Object.entries(space.customFoods)){need(id(key)&&key.startsWith('custom-')&&!baseFoodIds.includes(key)&&obj(f)&&f.id===key&&str(f.name)&&['g','mL'].includes(f.unit)&&Object.hasOwn(groups,f.group)&&obj(f.nutrients)&&typeof f.verified==='boolean'&&obj(f.source));for(const n of Object.keys(nutrients))need(Object.hasOwn(f.nutrients,n)&&(f.nutrients[n]===null||num(f.nutrients[n])));for(const field of ['label','url','id','state'])need(str(f.source[field]));need(!f.source.url||/^https?:\/\//.test(f.source.url));foodIds.add(key);}
  for(const r of space.customRecipes){need(obj(r)&&id(r.id)&&r.id.startsWith('recipe-')&&!recipeIds.has(r.id)&&str(r.name)&&Object.hasOwn(cats,r.category)&&Array.isArray(r.ingredients)&&r.ingredients.length>0&&num(r.portions)&&r.portions>0&&(r.cookedG===null||num(r.cookedG)&&r.cookedG>0)&&num(r.activeMin)&&num(r.totalMin)&&r.totalMin>=r.activeMin&&strings(r.steps)&&r.steps.length>0&&strings(r.tags)&&obj(r.prep)&&['fresh','raw-frozen','blanched-frozen','cooked-frozen'].includes(r.prep.mode));for(const i of r.ingredients)need(obj(i)&&foodIds.has(i.foodId)&&num(i.g)&&i.g>0);recipeIds.add(r.id);}
  for(const [key,m] of Object.entries(space.plans)){const match=key.match(/^(\d{4}-\d{2}-\d{2})-(breakfast|lunch|dinner|snack)$/);need(match&&date(match[1])&&obj(m)&&strings(m.recipeIds)&&m.recipeIds.every(r=>recipeIds.has(r))&&strings(m.people)&&new Set(m.people).size===m.people.length&&m.people.every(p=>members.has(p))&&obj(m.dishPeople)&&obj(m.size));for(const [r,list] of Object.entries(m.dishPeople))need(recipeIds.has(r)&&strings(list)&&list.every(p=>members.has(p)));for(const [p,size] of Object.entries(m.size))need(members.has(p)&&num(size)&&size>0);}
 }
 const selected=data.houses[data.house].members;need(selected.some(p=>p.id===data.person)&&selected.some(p=>p.id===data.planPerson));
 need(Array.isArray(data.records)&&Array.isArray(data.water)&&Array.isArray(data.feedback)&&obj(data.bought)&&Object.values(data.bought).every(num));
 const owner=r=>obj(r)&&spaces.includes(r.house)&&data.houses[r.house].members.some(p=>p.id===r.owner)&&date(r.day);
 for(const r of data.records){need(owner(r)&&str(r.id)&&str(r.text)&&Object.hasOwn(labels,r.period));if(r.actor!==undefined)need(data.houses[r.house].members.some(p=>p.id===r.actor));for(const field of ['portionText','note'])if(r[field]!==undefined)need(str(r[field]));need(r.kcal===null||Array.isArray(r.kcal)&&r.kcal.length===2&&r.kcal.every(num)&&r.kcal[0]<=r.kcal[1]);}
 for(const r of data.water)need(owner(r));for(const r of data.feedback)need(obj(r)&&str(r.text)&&str(r.time)&&!Number.isNaN(Date.parse(r.time)));
 return data;
}
function loadStoredState(){
 let raw=null;try{raw=localStorage.getItem(STORE);return raw===null?fresh():validateBackup(parseBackup(raw));}
 catch{if(typeof raw==='string'){try{let key=STORE+':recovery:'+Date.now();while(localStorage.getItem(key)!==null)key+='-1';localStorage.setItem(key,raw);}catch{return null;}setTimeout(()=>notify('旧资料格式无法读取，已保留恢复副本，本次使用空白记录。'),0);}return fresh();}
}
let s=loadStoredState();if(s===null){main.textContent='旧资料未能建立恢复副本，本次停止载入，原数据保持不变。';return;}
let modal=null,chooseFilter='protein',changeIndex=null,toastTimer=null,skillFilter='',bookSearch='',bookCategory='all',bookLimit=30,bookPage=0,recipePage=0,recipeQuery='',sheetTrigger=null,sheetScroll=0,sheetBodyStyle='';
const roughDrafts=Object.create(null);
const house=()=>s.houses[s.house];
const people=()=>house().members;
const findPerson=id=>people().find(p=>p.id===id)||people()[0];
const current=()=>findPerson(s.person);
const plannedPerson=()=>findPerson(s.planPerson);
const food=id=>D.foods[id]||house().customFoods[id];
const recipes=()=>D.recipes.concat(house().customRecipes);
const recipe=id=>{const active=recipes().find(r=>r.id===id);if(active)return {...active,...(D.cookingGuides?.[id]||{})};const retired=(D.retiredRecipes||[]).find(r=>r.id===id);return retired?{...retired,retired:true}:undefined;};
function syncCustomFoods(){for(const space of Object.values(s.houses))Object.assign(D.foods,space.customFoods);}
function save(){try{localStorage.setItem(STORE,JSON.stringify(s));}catch{notify('本机存储空间不足，请先导出备份。');}}
function notify(text){document.getElementById('toast-root').innerHTML=`<div class="toast" role="status">${h(text)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast-root').replaceChildren(),4200);}
const btn=(text,attrs='',cls='')=>`<button type="button" class="${cls}" ${attrs}>${text}</button>`;
const fmt=(value,key)=>value===null||!Number.isFinite(value)?'待补数据':(key==='kcal'||key==='sodium'||key==='calcium'?Math.round(value):Math.round(value*10)/10)+nutrients[key][1];
const nutText=(result,key)=>result.coverage[key]===0||result.values[key]===null?'数据未齐':(result.coverage[key]<1?'已知部分 ':'约')+fmt(result.values[key],key);
const modeName=mode=>({'raw-frozen':'原料生冻','blanched-frozen':'焯水后冷冻','cooked-frozen':'熟后冷冻',fresh:'现做 / 冷藏短备'}[mode]||'现做');
function pick(category,index=0){const choices=D.recipes.filter(r=>r.category===category&&r.defaultEligible!==false&&!r.id.includes('out'));return choices[index%choices.length]?.id;}
function newMeal(meal,offset=0){const recipeIds=meal==='breakfast'?[pick('breakfast',offset%3)]:meal==='snack'?[pick('snack',offset%3)]:[pick('grain',offset%2),pick('protein',offset%5),pick('veg',offset%5)];const defaultPeople=s.house==='solo'?people().map(p=>p.id):s.house==='care'?[]:meal==='breakfast'?['me','partner','child']:meal==='lunch'?['me','partner']:meal==='snack'?['me']:people().map(p=>p.id);return {recipeIds:recipeIds.filter(Boolean),people:defaultPeople,dishPeople:{},size:{}};}
function getMeal(day=s.day,meal=s.meal){const key=day+'-'+meal;if(!house().plans[key]){const offset=(new Date(day+'T12:00:00Z').getUTCDay()+6)%7;house().plans[key]=newMeal(meal,offset);}return house().plans[key];}
function recipePeople(m,id){return (m.dishPeople[id]||m.people).filter(p=>m.people.includes(p));}
function itemsFor(m,id){return E.mergeItems(m.recipeIds.filter(rid=>recipe(rid)&&recipePeople(m,rid).includes(id)).map(rid=>E.portion(recipe(rid),findPerson(id),m.size[id]||1)));}
function dayItems(id=s.planPerson,day=s.day){return E.mergeItems(Object.keys(labels).map(meal=>itemsFor(getMeal(day,meal),id)));}
function mealScore(m,id=s.planPerson,meal=s.meal){const items=itemsFor(m,id);return items.length?E.score(items,meal):{score:null,checks:[],note:'本餐未安排此人。'};}
function scoreLabel(score){return score===null?'未评分':score+'分';}
function personSelect(id,value=s.planPerson){return `<select class="select" id="${id}" aria-label="选择查看的成员">${people().map(p=>`<option value="${p.id}" ${p.id===value?'selected':''}>${h(p.name)}</option>`).join('')}</select>`;}
function groupChip(p,selected,attribute){return btn((selected?'✓ ':'')+h(p.name),`${attribute}="${p.id}" aria-pressed="${selected}"`,'chip '+(selected?'selected':''));}
function mealTabs(){return `<div class="tabs" role="group" aria-label="餐次">${Object.entries(labels).map(([key,name])=>btn(name,`data-meal="${key}"`,s.meal===key?'active':'')).join('')}</div>`;}
function topDate(){return `<div class="date-toolbar"><div><div class="tiny">${house().city==='guangzhou'?'广州':'上海'} · ${h(house().name)}</div><h1>${s.period==='week'?'一周安排':dateLabel(s.day)}</h1></div><div class="date-actions"><input class="input" type="date" id="day-picker" value="${s.day}" aria-label="选择日期"><div class="tabs period-tabs">${btn('每日','data-period="day"',s.period==='day'?'active':'')}${btn('一周','data-period="week"',s.period==='week'?'active':'')}</div></div></div>`;}
function planning(){return `${topDate()}${s.period==='week'?weekPage():dayPage()}`;}
function planningSummary(){const p=plannedPerson(),n=E.nutrition(dayItems(p.id));const m=getMeal(),score=mealScore(m);const scores=['breakfast','lunch','dinner'].map(key=>mealScore(getMeal(s.day,key),p.id,key)).filter(x=>x.score!==null);const avg=scores.length===3?Math.round(scores.reduce((a,x)=>a+x.score,0)/3):null;return `<section class="soft-panel stack"><div class="row"><div><div class="tiny">看谁的计划营养</div><h2>${h(p.name)}的今天</h2></div>${personSelect('plan-person')}</div><div class="grid2"><div><div class="subtle">${labels[s.meal]}搭配完整度</div><strong class="score-value">${scoreLabel(score.score)}</strong>${btn('看依据','data-score','ghost small')}</div><div><div class="subtle">全天搭配完整度</div><strong class="score-value">${avg===null?`${scores.length}/3餐已安排`:avg+'分'}</strong></div></div><p class="tiny">按主食、蛋白、蔬果、多样性四项检查；这不是疾病控制分，也不代表营养素一定够量。</p><div class="row"><span>全天计划：${n.coverage.kcal<1?'已知部分约':'约'}${fmt(n.values.kcal,'kcal')} · 蛋白质${n.coverage.protein<1?'已知部分':''}${fmt(n.values.protein,'protein')}</span>${btn('够不够 / 营养明细','data-nutrition','ghost')}</div>${!p.profileConfirmed?`<p class="tiny">个人目标尚待基础资料确认，先看计划用量与配方估算。</p>`:''}</section>`;}
function mealCard(r,index,m){return `<article class="meal-card"><div><h3 class="meal-title">${h(r.name)}</h3><div class="meal-meta">动手${r.activeMin}分钟 · ${modeName(r.prep.mode)}</div></div>${r.uricAcidNote?'<span class="tiny">尿酸关注 · 手动选择</span>':''}<div class="meal-actions">${btn('换菜',`data-change="${index}"`,'small')}${btn('做法',`data-recipe="${r.id}"`,'ghost small')}<details class="dish-more"><summary>更多</summary><div class="wrap">${btn('这道谁吃',`data-dish-people="${r.id}"`,'small')}${btn('不做这道',`data-remove-dish="${index}"`,'ghost small')}</div></details></div></article>`;}
function portionsPanel(m){return `<section class="panel stack portion-panel"><div class="row"><h2>每人分多少</h2><span class="tiny">${m.people.length}人 · 点开看原料</span></div>${m.people.map(id=>{const p=findPerson(id),items=itemsFor(m,id).filter(i=>food(i.foodId).group!=='condiment'),totals={};for(const i of items){const f=food(i.foodId),key=f.group+'|'+f.unit;totals[key]=(totals[key]||0)+i.g;}const glance=Object.entries(totals).map(([key,g])=>{const [group,unit]=key.split('|');return `${groups[group]}${Math.round(g)}${unit}`;}).join(' · ');return `<details class="person-portion" data-portion-person="${id}"><summary><strong>${h(p.name)}</strong><span class="portion-glance">${h(glance||'本餐未选菜')}</span><span class="portion-expand" aria-hidden="true">展开</span></summary><div class="portion-details">${items.map(i=>`<div class="portion-item"><span>${h(food(i.foodId).name)}</span><strong>${Math.round(i.g)}${food(i.foodId).unit}</strong></div>`).join('')}<label class="portion-adjust field">这顿份量<select class="select" data-size="${id}" aria-label="${h(p.name)}这顿份量">${[[.75,'少一点'],[1,'参考份'],[1.25,'多一点']].map(([v,t])=>`<option value="${v}" ${(m.size[id]||1)===v?'selected':''}>${t}</option>`).join('')}</select></label>${p.stage==='care'?'<p class="tiny">照护份量先按已有吞咽与饮食方案核对。</p>':''}</div></details>`;}).join('')||'<p class="empty">先勾选这顿谁吃。</p>'}${btn('看厨房总量','data-prep-total','primary')}<p class="tiny">以上是食物用量：米面干重，肉鱼虾及蔬菜为可食生重；并非营养素克数。</p></section>`;}
function dayPage(){const m=getMeal(),score=mealScore(m);return `<div class="plan-layout" data-plan-key="${s.house}|${s.day}|${s.meal}"><div class="plan-workspace stack"><section class="plan-controls panel stack">${mealTabs()}<div class="row diner-heading"><h2>这顿谁吃？</h2><div class="wrap">${btn('只我','data-only','ghost small')}${btn('全家','data-all','ghost small')}</div></div><div class="wrap diner-chips">${people().map(p=>groupChip(p,m.people.includes(p.id),'data-person')).join('')}</div></section><section class="plan-menu stack"><div class="section-heading row"><div><h2>${labels[s.meal]}吃这些</h2><p class="tiny">${h(plannedPerson().name)}的本餐搭配：${scoreLabel(score.score)} ${btn('看依据','data-score','ghost small')}</p></div>${btn('加一道','data-choose','primary')}</div><div class="meal-grid">${m.recipeIds.map((id,i)=>recipe(id)?mealCard(recipe(id),i,m):'').join('')||'<div class="empty">先从菜谱加一道，或自己选食材。</div>'}</div><div class="menu-actions">${btn('自己选食材','data-build','ghost')}</div></section><section class="panel prep-banner"><div class="row"><div><h3>一次分装，平日少切菜</h3><p class="tiny">主食、蛋白、蔬菜换着组合</p></div>${btn('看备餐包','data-open-prep','ghost small')}</div></section>${roughSection()}<p class="tiny privacy-note">电脑 / 手机通用测试版 · 数据仅保存在当前浏览器。换设备可在“我的”中导出和恢复备份；暂不自动同步。</p></div><aside class="plan-sidebar stack">${portionsPanel(m)}${planningSummary().replace('soft-panel stack','soft-panel stack nutrition-summary').replace('data-score','data-summary-score')}</aside></div>`;}
function weekPage(){const start=monday(s.day);return `<div class="stack"><section class="soft-panel row"><div><h2>一眼看一周</h2><p class="tiny">点餐次即可调整；只填空餐，保留已经改过的菜单。</p></div>${btn('套用一周参考','data-fill-week')}</section><div class="week-grid">${Array.from({length:7},(_,i)=>{const d=addDay(start,i);return `<section class="panel day-card"><div class="row"><h2>${dateLabel(d)}</h2>${btn('看这天',`data-day="${d}"`,'ghost small')}</div>${Object.entries(labels).map(([key,name])=>{const m=getMeal(d,key),sc=mealScore(m,s.planPerson,key);return `<div class="week-meal-row"><span>${name}</span><div><p>${m.recipeIds.map(id=>h(recipe(id)?.name||'')).join('、')||'待选'}</p><span class="tiny">${sc.score===null?(key==='snack'?'加餐':'未安排此人'):sc.score+'分'}</span></div>${btn('调整',`data-open-meal="${d}" data-meal-type="${key}" aria-label="调整${d}${name}"`,'ghost small')}</div>`;}).join('')}</section>`;}).join('')}</div></div>`;}
function roughSection(){const rows=s.records.filter(x=>x.house===s.house&&x.owner===s.person&&x.day===s.day);return `<section class="panel stack rough-panel"><div class="row"><h2>${h(current().name)} · 实吃随手记</h2>${personSelect('record-person',s.person)}</div><p class="subtle">大概记一下即可，计划餐的营养分析看上方。</p><textarea class="input" id="rough-text" data-draft-key="${h(s.house+'|'+s.person+'|'+s.day)}" placeholder="例如：早上吃了手掌大小的酸奶碗；下午一个苹果">${h(roughDrafts[s.house+'|'+s.person+'|'+s.day]||'')}</textarea><div class="wrap">${btn('记下','data-rough-save','primary')}${btn('这顿照计划吃了','data-log-plan')}${btn('喝了一杯水','data-water-add')}</div>${rows.map(x=>`<div class="check-row"><div><strong>${h(x.text)}</strong><p class="tiny">${labels[x.period]||'随手记'} · ${h(x.portionText||'原话保留')} ${x.kcal?'· 粗估'+Math.round(x.kcal[0])+'—'+Math.round(x.kcal[1])+'千卡':''}</p></div>${btn('删除',`data-record-remove="${x.id}"`,'ghost small')}</div>`).join('')}<p class="tiny">今天记了${rows.length}笔实吃、${s.water.filter(x=>x.house===s.house&&x.owner===s.person&&x.day===s.day).length}杯水。粗记不用于精确判定营养缺乏或超量，也不会改采购。</p></section>`;}
function allShopping(){const list=[],days=s.shopRange==='week'?Array.from({length:7},(_,i)=>addDay(monday(s.day),i)):[s.day];for(const day of days)for(const meal of Object.keys(labels)){const m=getMeal(day,meal);for(const id of m.people)list.push(itemsFor(m,id));}return E.mergeItems(list).filter(i=>food(i.foodId).group!=='condiment');}
function shopping(){const items=allShopping(),keyBase=s.house+'-'+s.shopRange+'-'+(s.shopRange==='week'?monday(s.day):s.day);return `<div class="stack"><div class="page-head"><div><div class="tiny">${house().name}</div><h1>照着买就好</h1></div>${btn('复制清单','data-copy-shop')}</div><div class="tabs">${btn('选中这天','data-shop-range="day"',s.shopRange==='day'?'active':'')}${btn('这一周','data-shop-range="week"',s.shopRange==='week'?'active':'')}</div><p class="tiny">计划净用量，米面干重、肉菜可食生重；包装和带骨带壳重量需另折算。</p>${Object.entries(groups).filter(([g])=>g!=='condiment').map(([g,label])=>{const selected=items.filter(i=>food(i.foodId).group===g);return selected.length?`<section class="panel"><h2>${label}</h2>${selected.map(i=>{const key=keyBase+'-'+i.foodId,bought=Number(s.bought[key]||0)>=i.g;return `<div class="check-row"><label class="row"><input type="checkbox" data-buy="${key}" data-grams="${i.g}" ${bought?'checked':''}><span>${h(food(i.foodId).name)}<br><span class="tiny">${Math.ceil(i.g)}${food(i.foodId).unit}${!bought&&s.bought[key]?' · 用量增加，需补买':''}</span></span></label>${btn('家里有',`data-have="${key}" data-grams="${i.g}"`,'ghost small')}</div>`;}).join('')}</section>`:'';}).join('')||'<div class="empty">先安排几顿饭，再来买菜。</div>'}</div>`;}
function standardItems(r){return E.portion(r,{portions:{}},1);}
function recipeSkill(id){const prefs=house().recipeSkills;return prefs&&typeof prefs==='object'&&['familiar','try'].includes(prefs[id])?prefs[id]:'';}
function skillLabel(id){return recipeSkill(id)==='familiar'?'我会做':recipeSkill(id)==='try'?'想尝试':'';}
function applyCatalogRevision(){
 const version=D.catalogVersion||1;if((s.catalogVersion||1)>=version)return false;
 let changed=0;const mapping=D.recipeReplacements||{},cutoff=today();
 for(const space of Object.values(s.houses))for(const [key,m] of Object.entries(space.plans)){
  if(key.slice(0,10)<cutoff)continue;
  const next=[];
  for(const old of m.recipeIds){
   if(!Object.hasOwn(mapping,old)){next.push(old);continue;}
   const replacement=mapping[old];changed++;
   if(replacement){next.push(replacement);if(m.dishPeople[old]&&!Object.hasOwn(m.dishPeople,replacement))m.dishPeople[replacement]=m.dishPeople[old];}
   delete m.dishPeople[old];
  }
  m.recipeIds=[...new Set(next)];
 }
 s.catalogVersion=version;
 if(changed)setTimeout(()=>notify('菜谱已更新：未来计划中的旧菜已按反馈调整；实吃记录和过去餐单保留。'),0);
 return changed>0;
}
function recipeNotes(r){return [...new Set([...(Array.isArray(r.healthNotes)?r.healthNotes:[]),r.safetyNote||r.uricAcidNote].filter(Boolean))].join('；');}
function recipeTags(r){return `<div class="wrap">${skillLabel(r.id)?`<span class="badge">${skillLabel(r.id)}</span>`:''}${r.noviceTips?.length||r.guideVersion?'<span class="badge">新手步骤</span>':''}${r.adapted?'<span class="badge">家庭改写</span>':r.sourcePages?.length?'<span class="badge">书页配方</span>':''}${r.defaultEligible===false?'<span class="badge">手动可选</span>':''}</div>`;}
function matchingLibraryRecipes(){return recipes().filter(r=>s.filter==='all'||r.category===s.filter).filter(r=>!skillFilter||recipeSkill(r.id)===skillFilter).filter(r=>!recipeQuery||r.name.includes(recipeQuery)||r.ingredients.some(i=>food(i.foodId)?.name.includes(recipeQuery)));}
function libraryRecipeResults(){const rows=matchingLibraryRecipes(),pages=Math.max(1,Math.ceil(rows.length/12));recipePage=Math.min(recipePage,pages-1);return `<div class="results-heading row"><span class="tiny">${rows.length}道菜 · 第${recipePage+1}/${pages}页</span></div><div class="recipe-grid">${rows.slice(recipePage*12,recipePage*12+12).map(r=>`<article class="panel recipe-card stack"><div><h2>${h(r.name)}</h2><p class="tiny">动手${r.activeMin}分钟 · ${modeName(r.prep.mode)}</p></div>${recipeTags(r)}${r.uricAcidNote?'<p class="tiny">尿酸关注 · 手动选择</p>':''}${btn('看做法',`data-recipe="${r.id}"`,'small')}</article>`).join('')||'<p class="empty">没有找到，换个关键词或筛选试试。</p>'}</div><div class="pagination">${btn('上一页',`data-recipe-page="prev" ${recipePage===0?'disabled':''}`)}<span class="page-count">${recipePage+1} / ${pages}</span>${btn('下一页',`data-recipe-page="next" ${recipePage>=pages-1?'disabled':''}`)}</div>`;}
function refreshRecipeResults(){const node=document.getElementById('recipe-results');if(node)node.innerHTML=libraryRecipeResults();}
function scrollCatalogResults(){const toolbar=document.querySelector('.library-toolbar');toolbar?.scrollIntoView({block:'start',behavior:'instant'});}
function library(){const seasonal=D.seasonal[house().city],tabs=[['all','全部菜谱'],...Object.entries(cats),['prep','冷冻备餐'],['season','当地食材'],['book','书页参考']];let body='';
 if(s.filter==='prep')body=`<section class="soft-panel row"><div><h2>一次分装，几顿换着做</h2><p class="tiny">按生冻、焯冻、熟后冻分别操作。</p></div>${btn('本周备菜汇总','data-batch-summary')}</section><div class="recipe-grid">${D.prepPacks.map(p=>`<section class="panel stack"><div class="row"><h2>${h(p.name)}</h2><span class="badge">${modeName(p.freezeType)}</span></div><p>${h(p.method)}</p><p class="tiny">${h(p.portionNote)}</p><p class="tiny">搭配：${p.useFor.map(h).join('、')}</p>${btn('用到选中这顿',`data-pack-use="${p.recipeId}"`)}</section>`).join('')}</div>`;
 else if(s.filter==='season')body=`<section class="soft-panel"><h2>${house().city==='guangzhou'?'广州':'上海'}秋冬采购候选</h2><p>${seasonal.autumnWinter.map(id=>h(food(id)?.name||id)).join('、')}</p><p class="tiny">${h(seasonal.note)}</p></section><section class="panel"><h2>冷冻常备另算</h2><p>秋葵、西兰花、彩椒、洋葱可作为备餐组件，按当地供应采购。</p></section>`;
 else if(s.filter==='book')body=bookReferencePage();
 else body=`<div class="library-search"><input class="input" id="recipe-search" value="${h(recipeQuery)}" aria-label="搜索菜名或食材" placeholder="搜菜名或食材，例如：三文鱼、鸡蛋"><select class="select" id="skill-filter" aria-label="按会不会做筛选"><option value="">全部做法</option><option value="familiar" ${skillFilter==='familiar'?'selected':''}>我会做</option><option value="try" ${skillFilter==='try'?'selected':''}>想尝试</option></select></div><div id="recipe-results">${libraryRecipeResults()}</div>`;
 return `<div class="stack library-page"><div class="page-head"><div><div class="tiny">${house().city==='guangzhou'?'广州':'上海'} · 简单选菜，按人分量</div><h1>备餐与菜谱</h1></div>${btn('自选食材','data-build')}</div><div class="library-toolbar"><div class="category-strip" role="group" aria-label="菜谱类别">${tabs.map(([key,text])=>btn(text,`data-filter="${key}" aria-pressed="${s.filter===key}"`,'chip '+(s.filter===key?'selected':''))).join('')}</div></div>${body}</div>`;}
function bookReferencePage(){const ready=(D.bookReferences||[]).filter(ref=>ref.recipeId&&recipe(ref.recipeId)).length;return `<details class="book-intro"><summary>${ready}条可直接选做 · 按菜名或食材找</summary><p class="tiny">书中有完整配方的保留原始数量；其余按检索资料整理成家庭参考配方，详情中可看改写说明与来源。用量用于备料和估算，按个人情况调整。</p></details><div class="library-search"><input class="input" id="book-search" value="${h(bookSearch)}" aria-label="搜索书页菜名" placeholder="搜索菜名，例如：瘦牛肉沙拉"><select class="select" id="book-category" aria-label="书页菜谱类别"><option value="all">全部类别</option>${Object.entries(cats).map(([key,name])=>`<option value="${key}" ${bookCategory===key?'selected':''}>${name}</option>`).join('')}</select></div><div id="book-reference-results">${bookReferenceItems()}</div>`;}
function matchingBookReferences(){return (D.bookReferences||[]).filter(r=>bookCategory==='all'||r.category===bookCategory).filter(r=>!bookSearch||r.name.includes(bookSearch)||recipe(r.recipeId)?.name.includes(bookSearch)||recipe(r.recipeId)?.ingredients.some(i=>food(i.foodId)?.name.includes(bookSearch)));}
function bookReferenceItems(){const matches=matchingBookReferences(),pages=Math.max(1,Math.ceil(matches.length/12));bookPage=Math.min(bookPage,pages-1);const start=bookPage*12;return `<div class="results-heading row"><span class="tiny">${matches.length}道 · 第${bookPage+1}/${pages}页</span></div><div class="reference-grid">${matches.slice(start,start+12).map(ref=>{const r=recipe(ref.recipeId);return `<article class="panel recipe-card stack"><div><h2>${h(ref.name)}</h2><span class="tiny">${h(cats[ref.category]||'参考')} · 书页${(ref.sourcePages||[]).join('、')}</span></div>${r?`<p class="tiny">${r.name!==ref.name?'做法：'+h(r.name)+' · ':''}动手${r.activeMin}分钟 · ${r.steps.length}步</p>${r.adapted?'<span class="tiny">家庭健康改写 · 可直接加入计划</span>':'<span class="tiny">已有原书配方 · 新手步骤</span>'}${btn('看做法',`data-recipe="${r.id}"`,'small')}`:btn('查看参考',`data-book-reference="${ref.id}"`,'small')}</article>`;}).join('')||'<p class="empty">没有找到，换个关键词试试。</p>'}</div><div class="pagination">${btn('上一页',`data-book-page="prev" ${bookPage===0?'disabled':''}`)}<span class="page-count">${bookPage+1} / ${pages}</span>${btn('下一页',`data-book-page="next" ${bookPage>=pages-1?'disabled':''}`)}</div>`;}
function refreshBookResults(){const node=document.getElementById('book-reference-results');if(node)node.innerHTML=bookReferenceItems();}
function bookReferenceSheet(id){const ref=(D.bookReferences||[]).find(r=>r.id===id);if(!ref)return;if(ref.recipeId&&recipe(ref.recipeId)){recipeSheet(ref.recipeId);return;}showSheet(ref.name,'<p>这条配方暂未载入，请刷新网页后重试。</p>');}
function recipeSheet(id){
 const r=recipe(id),per=standardItems(r),n=E.nutrition(per);modal={type:'recipe',id};
 const rows=items=>items.map(i=>`<div class="check-row"><span>${h(food(i.foodId).name)}</span><strong>${Math.round(i.g*10)/10}${food(i.foodId).unit}</strong></div>`).join('');
 const pantry=per.filter(i=>food(i.foodId).group==='condiment'&&i.foodId!=='water'),mainIngredients=per.filter(i=>food(i.foodId).group!=='condiment'||i.foodId==='water');
 const m=getMeal(),pids=(m.recipeIds.includes(id)?recipePeople(m,id):m.people),total=E.mergeItems(pids.map(pid=>E.portion(r,findPerson(pid),m.size[pid]||1)));
 const sources=(r.sourceRefs||[]).filter(ref=>ref?.url&&/^https?:\/\//.test(ref.url));
 const sourceAmount=r.originalIngredients?.length?`<details class="recipe-extra"><summary>查看原书配方数量</summary>${r.originalIngredients.map(i=>`<div class="check-row"><span>${h(i.name)}</span><span>${h(i.quantityText||((i.amount??'')+(i.unit||'')))}</span></div>`).join('')}<p class="tiny">${h(typeof r.originalYield==='object'?r.originalYield.label:r.originalYield||'原方未注明人份')}</p></details>`:'';
 showSheet(r.name,`<div class="cook-guide">${recipeTags(r)}<div class="recipe-facts"><span><strong>${r.activeMin}分钟</strong>动手</span><span><strong>${r.totalMin>=120?Math.round(r.totalMin/6)/10+'小时':r.totalMin+'分钟'}</strong>全程参考</span><span><strong>${r.portions>1?'整批'+r.portions+(r.portionLabel||'份'):'1参考份'}</strong>${modeName(r.prep.mode)}</span></div>${r.uricAcidNote?`<p class="notice">尿酸关注：${h(r.uricAcidNote)}</p>`:''}<h3>先备料 · 每${h(r.portionLabel||'参考份')}</h3>${rows(mainIngredients)}${pantry.length?`<details class="recipe-extra pantry"><summary>调味用量</summary>${rows(pantry)}</details>`:''}${pids.length?`<details class="recipe-extra"><summary>按本餐选中的${pids.length}人备料</summary><p class="tiny">${pids.map(pid=>h(findPerson(pid).name)).join('、')}；已按各人份量设置计算。</p>${rows(total)}</details>`:''}${r.portions>1?`<details class="recipe-extra"><summary>整批${r.portions}${h(r.portionLabel||'份')}制作原料</summary>${rows(r.ingredients)}</details>`:''}<h3>照着做${r.portions>1?' · 按整批制作':''}</h3><p class="tiny">每完成一步可以勾一下。时间受锅具、火力和食材大小影响，熟透判断也要一起看。</p><div class="cook-steps">${r.steps.map((step,i)=>`<label class="cook-step"><input type="checkbox" aria-label="完成第${i+1}步"><span class="step-number">${i+1}</span><span class="step-text">${h(step)}</span></label>`).join('')}</div>${r.noviceTips?.length?`<section class="novice-tips"><h3>第一次做，记住这几点</h3>${r.noviceTips.map(t=>`<p>${h(t)}</p>`).join('')}</section>`:''}${r.healthNotes?.length?`<details class="recipe-extra"><summary>健康搭配与备餐提示</summary>${r.healthNotes.map(t=>`<p class="tiny">${h(t)}</p>`).join('')}</details>`:''}<details class="recipe-extra"><summary>份量依据与参考来源</summary>${r.basisNote?`<p class="tiny">${h(r.basisNote)}</p>`:''}${r.sourcePages?.length?`<p class="tiny">菜单／原书来源页：${r.sourcePages.join('、')}。</p>`:''}${sources.map(ref=>`<p class="tiny">${h(ref.relation||'参考资料')}：<a href="${h(ref.url)}" target="_blank" rel="noreferrer">${h(ref.title)}</a></p>`).join('')}${!sources.length&&r.sourceIds?.length?r.sourceIds.map(sid=>{const ref=D.sources.find(x=>x.id===sid);return ref?`<p class="tiny">${ref.url?`<a href="${h(ref.url)}" target="_blank" rel="noreferrer">${h(ref.title||ref.label||ref.name||'资料来源')}</a>`:h(ref.title||ref.label||ref.name||'用户提供书页')}</p>`:'';}).join(''):''}</details>${sourceAmount}<details class="recipe-extra"><summary>配方营养估算</summary><p>能量${nutText(n,'kcal')} · 蛋白质${nutText(n,'protein')} · 碳水${nutText(n,'carbs')}</p><p class="tiny">参考原料逐项估算；未匹配成分保持未知，不把已知小计当完整营养。成品熟重${r.cookedG?'约'+r.cookedG+'g':'尚未实测'}。</p></details><label class="field">这道菜对我家<select class="select" id="recipe-skill" data-recipe-id="${r.id}"><option value="">还没标记</option><option value="familiar" ${recipeSkill(r.id)==='familiar'?'selected':''}>我会做</option><option value="try" ${recipeSkill(r.id)==='try'?'selected':''}>想尝试</option></select></label></div>`,r.retired?'<p class="tiny">历史菜谱保留条目。</p>':btn('加入这顿，按人数算量',`data-add-detail="${id}"`,'primary'));
}
function myPage(){const p=current();return `<div class="stack"><div class="page-head"><div><div class="tiny">${house().name} · 个人记录分开保存</div><h1>我的设置</h1></div>${personSelect('record-person',s.person)}</div><section class="panel"><h2>先填一次，之后少操作</h2><form id="profile-form"><div class="form-grid"><label class="field">名字<input class="input" name="name" value="${h(p.name)}" required maxlength="20"></label><label class="field">年龄<input class="input" name="age" type="number" min="1" max="120" value="${p.age??''}"></label><label class="field">身高 cm<input class="input" name="height" type="number" min="40" max="230" value="${p.height??''}"></label><label class="field">体重 kg<input class="input" name="weight" type="number" min="3" max="300" step=".1" value="${p.weight??''}"></label></div><div class="section-title">想重点关注</div><div class="wrap">${[['glucose','血糖'],['pressure','血压'],['lipids','血脂'],['uric','尿酸']].map(([key,name])=>`<label class="chip ${p.focus.includes(key)?'selected':''}"><input type="checkbox" name="focus" value="${key}" ${p.focus.includes(key)?'checked':''}>${name}</label>`).join('')}</div><p class="tiny">这是关注方向，不是自动诊断。仅凭某一次血压、血糖数值不判断是否患病。</p><details><summary>补充生理阶段、活动与已有医嘱</summary><div class="form-grid"><label class="field">生理阶段<select class="select" name="stage">${[['adult','一般成人'],['lactating','哺乳期'],['child','儿童'],['elder','老年人'],['care','需要照护']].map(([key,text])=>`<option value="${key}" ${p.stage===key?'selected':''}>${text}</option>`).join('')}</select></label><label class="field">性别（营养参考）<select class="select" name="sex">${[['unknown','暂不填写'],['female','女'],['male','男']].map(([key,text])=>`<option value="${key}" ${p.sex===key?'selected':''}>${text}</option>`).join('')}</select></label><label class="field">特殊饮食要求<select class="select" name="specialDiet"><option value="unknown" ${p.specialDiet?'selected':''}>有 / 还不清楚</option><option value="no" ${!p.specialDiet?'selected':''}>已确认不需要</option></select></label><label class="field">日常活动<select class="select" name="activity">${['待补充','以久坐为主','轻度活动','中度活动','较高活动'].map(v=>`<option ${p.activity===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="field">其他关注、过敏或医生已有要求<textarea class="input" name="notes" maxlength="500" placeholder="照护者可补吞咽、食物质地、限液等已有方案">${h(p.notes||'')}</textarea></label></details><button class="primary" type="submit">保存本人资料</button><p class="tiny">普通成人参考与孕哺、儿童、老人、病患分开。身高体重等不齐时，不虚构精确个人目标。</p></form></section><section class="panel"><h2>这个家庭在哪里</h2><label class="field">城市<select class="select" id="city-picker"><option value="shanghai" ${house().city==='shanghai'?'selected':''}>上海</option><option value="guangzhou" ${house().city==='guangzhou'?'selected':''}>广州</option></select></label><p class="tiny">城市只影响当地食材候选，不会覆盖已安排的餐单。</p></section><section class="panel"><h2>喝水提醒计划</h2><p>白天分散提醒，晚上结束后不催补。饭后不设统一禁水规则。</p><div class="form-grid"><label class="field">开始<input class="input" type="time" id="water-start" value="${p.waterStart||'08:00'}"></label><label class="field">结束<input class="input" type="time" id="water-end" value="${p.waterEnd||'20:00'}"></label></div>${btn('保存提醒时段','data-save-water')}${btn('预览提醒','data-notification-preview','ghost')}<p class="tiny">手机通知未启用：此版本只保存设置，不会锁屏推送。需要照护者按已有饮水/吞咽方案安排。</p></section><section class="panel"><h2>测试与备份</h2><div class="wrap">${btn('写测试反馈','data-feedback')}${btn('导出本机备份','data-export')}${btn('恢复备份','data-import')}${btn('来源与计算说明','data-sources','ghost')}</div><p class="tiny">测试链接可转发。数据只在当前浏览器；不同手机暂不共享、没有真实账号权限。请勿清理浏览器数据后仍期待记录保留。</p><input type="file" id="import-file" accept="application/json" hidden></section></div>`;}
function showSheet(title,body,actions=''){
 if(!modalRoot.firstElementChild){sheetTrigger=document.activeElement;sheetScroll=window.scrollY;sheetBodyStyle=document.body.style.cssText;const gap=window.innerWidth-document.documentElement.clientWidth;document.body.style.position='fixed';document.body.style.top=-sheetScroll+'px';document.body.style.left='0';document.body.style.right='0';document.body.style.width='100%';document.body.style.overflow='hidden';if(gap>0)document.body.style.paddingRight=gap+'px';}
 modalRoot.innerHTML=`<div class="modal-backdrop" data-backdrop><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title" tabindex="-1"><div class="sheet-head row"><h2 id="sheet-title">${h(title)}</h2>${btn('关闭','data-close','ghost')}</div><div class="sheet-body">${body}</div>${actions?`<div class="sheet-actions">${actions}</div>`:''}</section></div>`;
 modalRoot.querySelector('[data-close]')?.focus({preventScroll:true});
}
function closeSheet(){if(!modalRoot.firstElementChild){modal=null;changeIndex=null;return;}modalRoot.replaceChildren();document.body.style.cssText=sheetBodyStyle;window.scrollTo({top:sheetScroll,behavior:'instant'});if(sheetTrigger?.isConnected)sheetTrigger.focus({preventScroll:true});modal=null;changeIndex=null;sheetTrigger=null;}
function nutritionSheet(){const p=plannedPerson(),items=dayItems(p.id),n=E.nutrition(items),goals=E.goals(p);showSheet(p.name+' · 当天计划营养',`<div class="notice">按实际食材种类和配方克数累计；不同菜、不同做法不能等重量视为同营养。以下是配方估算，尚未按品牌、烹饪损失全部校准。</div><div class="nutrient-list">${Object.entries(nutrients).map(([key,[name]])=>{const g=goals[key],status=E.status(n.values[key],g,n.coverage[key]);return `<div class="nutrient"><div><strong>${name}</strong><p class="tiny">${g?h(g.source||'已确认参考'):'个人目标待确认'}${n.coverage[key]<1?' · 存在未匹配数据':''}</p></div><div style="text-align:right"><strong>${fmt(n.values[key],key)}</strong><p class="status-${status.kind}">${h(status.label)}</p></div></div>`;}).join('')}</div><p class="tiny">“达到推荐参考”不等于越多越好；蛋白超过RNI不自动判超量，钠限量不是需要凑满的目标。资料不全时不作医学达标判断。</p>`);}
function scoreSheet(){const p=plannedPerson(),m=getMeal(),result=mealScore(m,p.id);showSheet(labels[s.meal]+' · '+scoreLabel(result.score),`${result.checks.map(c=>`<div class="check-row"><span>${c.passed?'✓':'○'} ${h(c.label)}</span><span>${c.passed?c.points:0}/${c.points}</span></div>`).join('')}<div class="notice">${h(result.note||'') }<br>这是本产品公开的搭配完整度检查，不是经过医学验证的健康风险评分。营养是否够量还要看全天营养、个人目标和数据完整度。</div>`);}
function totalSheet(){const m=getMeal(),totals=E.mergeItems(m.people.map(id=>itemsFor(m,id))).filter(i=>food(i.foodId).group!=='condiment');showSheet('这顿厨房总量',`${totals.map(i=>`<div class="check-row"><span>${h(food(i.foodId).name)}</span><strong>${Math.ceil(i.g)}${food(i.foodId).unit}</strong></div>`).join('')||'<p>这顿还没有选人或选菜。</p>'}<p class="tiny">净可食生重，含所有勾选的人；采购带骨、带壳食材另需换算。每个人的分量已在主页面逐行列出。</p>`);}
function chooseSheet(){const currentRecipe=changeIndex===null?null:recipe(getMeal().recipeIds[changeIndex]);const category=chooseFilter||(currentRecipe?.category||'protein');modal={type:'choose'};showSheet(currentRecipe?'替换 '+currentRecipe.name:'加入这顿',`<div class="wrap">${Object.entries(cats).map(([key,text])=>btn(text,`data-choose-filter="${key}"`,'chip '+(category===key?'selected':''))).join('')}</div><div class="recipe-list">${recipes().filter(r=>r.category===category).map(r=>`<div class="recipe-item row"><div><strong>${h(r.name)}</strong><p class="tiny">动手${r.activeMin}分钟 · ${modeName(r.prep.mode)}</p>${r.uricAcidNote?`<p class="tiny">尿酸关注：${h(r.uricAcidNote)}</p>`:''}</div>${btn(currentRecipe?'替换成这道':'加入',`data-use="${r.id}"`)}</div>`).join('')}</div>`,btn('自己选食材','data-build','primary'));}
function useRecipe(id){const m=getMeal(),before=E.nutrition(dayItems());if(changeIndex===null)m.recipeIds.push(id);else m.recipeIds[changeIndex]=id;const after=E.nutrition(dayItems());const compared=E.compare(before,after);save();closeSheet();render();const delta=compared.protein===null?null:Math.round(compared.protein*10)/10;notify('计划已重算'+(delta===null?'':`，全天蛋白质${delta>=0?'+':''}${delta}g（配方估算）`)+'；实际记录保持原样。');}
function builderSheet(){modal={type:'builder'};const choices=baseFoodIds.concat(Object.keys(house().customFoods)).filter(id=>food(id).group!=='condiment');showSheet('自己选食材',`<label class="field">菜名<input class="input" id="custom-name" placeholder="例如：我家的肉饼蒸蛋" maxlength="50"></label><label class="field">分类<select class="select" id="custom-category">${Object.entries(cats).map(([key,text])=>`<option value="${key}" ${key==='protein'?'selected':''}>${text}</option>`).join('')}</select></label><input class="input" id="food-search" placeholder="找食材，如豆腐、西兰花"><p class="tiny">先勾食材，再填1标准份所需的原料生重。</p><div id="ingredient-options">${choices.map(id=>`<div class="ingredient-row" data-food-name="${h(food(id).name)}"><label><input type="checkbox" data-custom-food="${id}">${h(food(id).name)}</label><input class="input" type="number" min="1" max="3000" step="5" data-custom-qty="${id}" value="100" disabled aria-label="${h(food(id).name)}标准份用量"><span>${food(id).unit}</span></div>`).join('')}</div><details><summary>没有找到？新增食材</summary><input class="input" id="new-food-name" placeholder="食材名称" maxlength="30"><select class="select" id="new-food-group">${Object.entries(groups).filter(([key])=>key!=='condiment').map(([key,text])=>`<option value="${key}">${text}</option>`).join('')}</select>${btn('加入候选','data-new-food')}<p class="tiny">没有营养数据的新食材会保留未知，不填零。</p></details>`,btn('保存为家庭菜谱并用于这顿','data-save-custom','primary'));}
function dishPeopleSheet(id){const m=getMeal();modal={type:'dishPeople',id};showSheet(recipe(id).name+' · 谁吃',`${m.people.map(pid=>`<label class="check-row"><span>${h(findPerson(pid).name)}</span><input type="checkbox" data-dish-check="${pid}" ${recipePeople(m,id).includes(pid)?'checked':''}></label>`).join('')||'<p>先在主页面选择这顿用餐的人。</p>'}`,btn('保存这道的就餐人','data-save-dish-people','primary'));}
function batchSummary(){const start=monday(s.day),counts={};for(let i=0;i<7;i++)for(const meal of Object.keys(labels)){const m=getMeal(addDay(start,i),meal);for(const id of m.recipeIds){const r=recipe(id);if(r?.prep.mode!=='fresh')counts[id]=(counts[id]||0)+recipePeople(m,id).length;}}showSheet('本周备菜汇总',`${Object.entries(counts).map(([id,count])=>`<div class="check-row"><div><strong>${h(recipe(id).name)}</strong><p class="tiny">${modeName(recipe(id).prep.mode)}</p></div><span>${count}份参考分装</span></div>`).join('')||'<p>当前菜单的冷冻组件还不多。可以先在备餐页选择主食、蛋白和蔬菜包，再用于几顿。</p>'}<p class="tiny">这里的份数按参与人数汇总；具体净用量请看采购页。焯水原料不等于即食菜；贴日期、分装并按原料状态烹调或彻底复热。</p>`);}
function feedbackSheet(){modal={type:'feedback'};showSheet('把测试意见带回这个聊天',`<label class="field">哪一步不方便，期望怎样<textarea class="input" id="feedback-text" placeholder="例如：广州家选两位长辈后，采购量想按三天合并"></textarea></label><p class="tiny">反馈先保存在本机，复制后发给我；不会自动发送给其他人。</p>`,btn('保存并复制反馈','data-save-feedback','primary'));}
async function copy(text){try{await navigator.clipboard.writeText(text);notify('已复制，可以粘贴发给我。');}catch{showSheet('复制这段文字',`<textarea class="input" rows="8" readonly>${h(text)}</textarea>`);}}
function render(){const oldPlan=document.querySelector('.plan-layout'),oldPlanKey=oldPlan?.dataset.planKey,openPeople=[...document.querySelectorAll('.person-portion[open]')].map(el=>el.dataset.portionPerson);const draft=document.getElementById('rough-text');if(draft)roughDrafts[draft.dataset.draftKey]=draft.value;syncCustomFoods();document.body.dataset.view=s.view;document.getElementById('house-picker').value=s.house;main.innerHTML=s.view==='plan'?planning():s.view==='shop'?shopping():s.view==='library'?library():myPage();if(document.querySelector('.plan-layout')?.dataset.planKey===oldPlanKey)document.querySelectorAll('.person-portion').forEach(el=>el.open=openPeople.includes(el.dataset.portionPerson));if(['shop','me'].includes(s.view)){const content=main.firstElementChild,panels=[...content.children].filter(el=>el.tagName==='SECTION'),grid=document.createElement('div');grid.className=s.view==='shop'?'shopping-grid':'settings-grid';if(panels.length){panels[0].before(grid);panels.forEach(el=>grid.append(el));}}document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===s.view);b.setAttribute('aria-current',b.dataset.nav===s.view?'page':'false');});}
document.addEventListener('click',async event=>{if(event.target.hasAttribute('data-backdrop')){closeSheet();return;}const b=event.target.closest('button');if(!b)return;
 if(b.dataset.bookReference)bookReferenceSheet(b.dataset.bookReference);
 else if(b.hasAttribute('data-book-more')){bookPage++;refreshBookResults();}
 else if(b.dataset.completeBook){const ref=(D.bookReferences||[]).find(r=>r.id===b.dataset.completeBook);if(ref){changeIndex=null;builderSheet();document.getElementById('custom-name').value=ref.name;document.getElementById('custom-category').value=ref.category;notify('按你家做法补齐原料和用量，再保存为可排餐菜谱。');}}
 else if(b.dataset.recipePage){recipePage=Math.max(0,recipePage+(b.dataset.recipePage==='next'?1:-1));refreshRecipeResults();scrollCatalogResults();}
 else if(b.dataset.bookPage){bookPage=Math.max(0,bookPage+(b.dataset.bookPage==='next'?1:-1));refreshBookResults();scrollCatalogResults();}
 else if(b.dataset.openMeal){s.day=b.dataset.openMeal;s.meal=b.dataset.mealType;s.period='day';s.view='plan';render();window.scrollTo({top:0,behavior:'instant'});}
 else if(b.dataset.nav){s.view=b.dataset.nav;closeSheet();render();window.scrollTo({top:0,behavior:'instant'});}
 else if(b.dataset.period){s.period=b.dataset.period;render();}
 else if(b.dataset.meal){s.meal=b.dataset.meal;render();}
 else if(b.dataset.day){s.day=b.dataset.day;s.period='day';render();window.scrollTo({top:0,behavior:'instant'});}
 else if(b.hasAttribute('data-only')){getMeal().people=[current().id];render();}
 else if(b.hasAttribute('data-all')){getMeal().people=people().map(p=>p.id);render();}
 else if(b.dataset.person){const m=getMeal(),id=b.dataset.person;m.people=m.people.includes(id)?m.people.filter(p=>p!==id):m.people.concat(id);render();}
 else if(b.hasAttribute('data-score')||b.hasAttribute('data-summary-score'))scoreSheet();
 else if(b.hasAttribute('data-nutrition'))nutritionSheet();
 else if(b.hasAttribute('data-prep-total'))totalSheet();
 else if(b.hasAttribute('data-open-prep')){s.view='library';s.filter='prep';render();window.scrollTo({top:0,behavior:'instant'});}
 else if(b.hasAttribute('data-choose')){changeIndex=null;chooseFilter=s.meal==='breakfast'?'breakfast':s.meal==='snack'?'snack':'protein';chooseSheet();}
 else if(b.dataset.change!==undefined){changeIndex=Number(b.dataset.change);chooseFilter=recipe(getMeal().recipeIds[changeIndex]).category;chooseSheet();}
 else if(b.dataset.chooseFilter){chooseFilter=b.dataset.chooseFilter;chooseSheet();}
 else if(b.dataset.use)useRecipe(b.dataset.use);
 else if(b.dataset.addDetail){const id=b.dataset.addDetail;changeIndex=null;useRecipe(id);}
 else if(b.dataset.packUse){changeIndex=null;useRecipe(b.dataset.packUse);s.view='plan';render();window.scrollTo({top:0,behavior:'instant'});}
 else if(b.dataset.removeDish!==undefined){getMeal().recipeIds.splice(Number(b.dataset.removeDish),1);render();notify('这道已移出计划，分量、营养与采购已重算。');}
 else if(b.dataset.recipe)recipeSheet(b.dataset.recipe);
 else if(b.dataset.dishPeople)dishPeopleSheet(b.dataset.dishPeople);
 else if(b.hasAttribute('data-save-dish-people')){getMeal().dishPeople[modal.id]=[...modalRoot.querySelectorAll('[data-dish-check]:checked')].map(i=>i.dataset.dishCheck);closeSheet();render();}
 else if(b.hasAttribute('data-close'))closeSheet();
 else if(b.hasAttribute('data-build'))builderSheet();
 else if(b.hasAttribute('data-new-food')){const name=document.getElementById('new-food-name').value.trim();if(name){const id='custom-'+s.house+'-'+Date.now();house().customFoods[id]={id,name,unit:'g',group:document.getElementById('new-food-group').value,nutrients:Object.fromEntries(Object.keys(nutrients).map(k=>[k,null])),verified:false,source:{label:'家庭新增，成分待匹配',url:'',id,state:'可食生重'}};syncCustomFoods();const row=document.createElement('div');row.className='ingredient-row';row.dataset.foodName=name;row.innerHTML=`<label><input type="checkbox" data-custom-food="${id}" checked>${h(name)}</label><input class="input" type="number" min="1" max="3000" step="5" data-custom-qty="${id}" value="100" aria-label="${h(name)}用量"><span>g</span>`;document.getElementById('ingredient-options').append(row);notify('食材已加到候选，营养保持未知。');}}
 else if(b.hasAttribute('data-save-custom')){const ingredients=[...modalRoot.querySelectorAll('[data-custom-food]:checked')].map(el=>({foodId:el.dataset.customFood,g:Number(modalRoot.querySelector(`[data-custom-qty="${el.dataset.customFood}"]`).value)})).filter(i=>i.g>0);if(!ingredients.length){notify('先勾选至少一种食材并填写用量。');return;}const id='recipe-'+s.house+'-'+Date.now();house().customRecipes.push({id,name:document.getElementById('custom-name').value.trim()||'家中自选搭配',category:document.getElementById('custom-category').value,ingredients,portions:1,cookedG:null,activeMin:15,totalMin:20,steps:['按自家做法准备这些食材。','做法、成品重量与冷冻方式可继续标准化。'],prep:{mode:'fresh'},tags:['家庭自选'],estimated:true});useRecipe(id);}
 else if(b.hasAttribute('data-rough-save')){const text=document.getElementById('rough-text').value.trim().slice(0,400);if(!text){notify('写一句吃了什么就可以。');return;}const draft=document.getElementById('rough-text');delete roughDrafts[draft.dataset.draftKey];draft.value='';const estimate=E.roughLog(text);s.records.push({id:'record-'+Date.now(),house:s.house,owner:s.person,actor:s.person,day:s.day,text,period:estimate.period||s.meal,portionText:estimate.portionText||'粗略记录',kcal:estimate.kcal||null,note:estimate.note});render();notify('已粗记，不影响备餐计划。');}
 else if(b.hasAttribute('data-log-plan')){const n=E.nutrition(itemsFor(getMeal(),s.person));const key='plan-'+s.house+'-'+s.person+'-'+s.day+'-'+s.meal;const entry={id:key,house:s.house,owner:s.person,actor:s.person,day:s.day,text:getMeal().recipeIds.filter(id=>recipePeople(getMeal(),id).includes(s.person)).map(id=>recipe(id).name).join('、')||'这顿未安排本人',period:s.meal,portionText:'按本次计划份量确认',kcal:n.coverage.kcal===1?[n.values.kcal*.85,n.values.kcal*1.15]:null};s.records=s.records.filter(x=>x.id!==key).concat(entry);render();notify('已确认这顿；以后改菜单不会自动改实吃记录。');}
 else if(b.dataset.recordRemove){s.records=s.records.filter(x=>!(x.id===b.dataset.recordRemove&&x.house===s.house&&x.owner===s.person));render();}
 else if(b.hasAttribute('data-water-add')){s.water.push({house:s.house,owner:s.person,day:s.day});render();notify('已记一杯水。');}
 else if(b.dataset.filter){s.filter=b.dataset.filter;recipePage=0;recipeQuery='';bookPage=0;render();scrollCatalogResults();}
 else if(b.hasAttribute('data-batch-summary'))batchSummary();
 else if(b.dataset.shopRange){s.shopRange=b.dataset.shopRange;render();}
 else if(b.dataset.have){s.bought[b.dataset.have]=Number(b.dataset.grams);render();}
 else if(b.hasAttribute('data-copy-shop'))copy(allShopping().map(i=>`${food(i.foodId).name} ${Math.ceil(i.g)}${food(i.foodId).unit}`).join('\n'));
 else if(b.hasAttribute('data-fill-week')){const start=monday(s.day);for(let i=0;i<7;i++)for(const meal of Object.keys(labels)){const key=addDay(start,i)+'-'+meal;if(!house().plans[key])house().plans[key]=newMeal(meal,i);}render();notify('空餐已用参考菜单补齐，没有覆盖已修改的餐单。');}
 else if(b.hasAttribute('data-save-water')){current().waterStart=document.getElementById('water-start').value;current().waterEnd=document.getElementById('water-end').value;notify('时段已保存；此版手机通知尚未启用。');}
 else if(b.hasAttribute('data-notification-preview'))showSheet('喝水提醒 · 样式预览','<p>现在方便喝几口水吗？</p><p class="subtle">稍后提醒 / 今天暂停</p><div class="notice">这只是提醒文案预览，没有申请或启用手机通知。错过的提醒不累计成睡前催喝。</div>');
 else if(b.hasAttribute('data-feedback'))feedbackSheet();
 else if(b.hasAttribute('data-save-feedback')){const text=document.getElementById('feedback-text').value.trim();if(text){const message=`好好吃饭测试反馈\n页面：${s.view}\n家庭：${house().name}（${house().city==='guangzhou'?'广州':'上海'}）\n${text}`;s.feedback.push({text:message,time:new Date().toISOString()});closeSheet();await copy(message);}}
 else if(b.hasAttribute('data-export')){const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='好好吃饭-本机备份-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 else if(b.hasAttribute('data-import'))document.getElementById('import-file').click();
 else if(b.hasAttribute('data-sources'))showSheet('来源与计算说明',`<p>营养＝每100g成分 × 原料可食生重，逐项相加。熟重、品牌、烹调留存未校准的部分保持估算。</p><p>食物重不等于营养素重：鸡肉与豆腐、生菜与西兰花需按各自条目重算，不能按同克数互换。</p><p>未知值不填零；RNI/AI不是安全上限，钠限量不是需吃满的目标。</p>${D.sources.map(source=>source.url?`<p><a target="_blank" rel="noreferrer" href="${h(source.url)}">${h(source.title||source.label||source.name||'来源')}</a></p>`:`<p>${h(source.title||source.label||source.name||'用户书页参考')}</p>`).join('')}<p class="tiny">测试版不提供诊断、用药或吞咽治疗建议；记录覆盖不足时不判断长期营养缺乏。</p>`);
 save();
});
document.addEventListener('change',event=>{const el=event.target;
 if(el.id==='house-picker'){s.house=el.value;s.person=people()[0].id;s.planPerson=s.person;closeSheet();render();}
 else if(el.id==='day-picker'){if(el.value)s.day=el.value;render();}
 else if(el.id==='plan-person'){s.planPerson=el.value;render();}
 else if(el.id==='record-person'){s.person=el.value;render();}
 else if(el.dataset.size){getMeal().size[el.dataset.size]=Number(el.value);render();}
 else if(el.dataset.buy){s.bought[el.dataset.buy]=el.checked?Number(el.dataset.grams):0;render();}
 else if(el.id==='city-picker'){house().city=el.value;render();}
 else if(el.dataset.customFood){modalRoot.querySelector(`[data-custom-qty="${el.dataset.customFood}"]`).disabled=!el.checked;}
 else if(el.id==='skill-filter'){skillFilter=el.value;recipePage=0;refreshRecipeResults();}
 else if(el.id==='book-category'){bookCategory=el.value;bookPage=0;refreshBookResults();}
 else if(el.id==='recipe-skill'){const id=el.dataset.recipeId;house().recipeSkills=house().recipeSkills||{};if(el.value)house().recipeSkills[id]=el.value;else delete house().recipeSkills[id];if(s.view==='library')render();notify('这道菜的熟悉程度已保存在本家庭。');}
 else if(el.id==='import-file'&&el.files[0]){const file=el.files[0];if(file.size>2000000){notify('备份文件太大，未导入。');return;}file.text().then(text=>{
  let previousState,previousRaw,previousFoods,changed=false;
  try{const candidate=validateBackup(parseBackup(text));previousRaw=localStorage.getItem(STORE);previousState=s;previousFoods={...D.foods};s=candidate;changed=true;applyCatalogRevision();render();localStorage.setItem(STORE,JSON.stringify(s));notify('本机备份已恢复。');}
  catch{if(changed){s=previousState;for(const id of Object.keys(D.foods))if(!Object.hasOwn(previousFoods,id))delete D.foods[id];Object.assign(D.foods,previousFoods);try{if(localStorage.getItem(STORE)!==previousRaw){if(previousRaw===null)localStorage.removeItem(STORE);else localStorage.setItem(STORE,previousRaw);}}catch{}try{render();}catch{}}notify('导入未完成，现有资料保留。');}
 }).catch(()=>notify('备份读取失败，现有资料保留。'));return;}
 save();
});
document.addEventListener('input',event=>{if(event.target.id==='food-search'){const query=event.target.value.trim();modalRoot.querySelectorAll('[data-food-name]').forEach(row=>row.hidden=!row.dataset.foodName.includes(query));}else if(event.target.id==='book-search'){bookSearch=event.target.value.trim();bookPage=0;refreshBookResults();}else if(event.target.id==='recipe-search'){recipeQuery=event.target.value.trim();recipePage=0;refreshRecipeResults();}else if(event.target.id==='rough-text'){roughDrafts[event.target.dataset.draftKey]=event.target.value;}});
document.addEventListener('submit',event=>{if(event.target.id!=='profile-form')return;event.preventDefault();const f=new FormData(event.target),p=current();Object.assign(p,{name:String(f.get('name')).trim()||p.name,age:Number(f.get('age'))||null,height:Number(f.get('height'))||null,weight:Number(f.get('weight'))||null,focus:f.getAll('focus'),sex:f.get('sex'),stage:f.get('stage'),activity:f.get('activity'),specialDiet:f.get('specialDiet')!=='no',notes:String(f.get('notes')||'').slice(0,500),profileConfirmed:true});save();render();notify('个人资料已保存，适用的通用参考已更新；特殊需求仍待确认。');});
document.addEventListener('keydown',e=>{if(!modalRoot.childElementCount)return;if(e.key==='Escape'){e.preventDefault();closeSheet();}else if(e.key==='Tab'){const nodes=[...modalRoot.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],summary,[tabindex="0"]')].filter(node=>node.getClientRects().length);if(!nodes.length){e.preventDefault();modalRoot.querySelector('.sheet').focus();return;}const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||!modalRoot.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!modalRoot.contains(document.activeElement))){e.preventDefault();first.focus();}}});
syncCustomFoods();applyCatalogRevision();render();save();
})();
